import{_ as a,o as n,c as i,ah as s}from"./chunks/framework.CmTHHbTK.js";const o="/projects/AiNovaPro/en/latest/assets/image2.C6-fOXe5.webp",r="/projects/AiNovaPro/en/latest/assets/image3.BAvv3SrB.webp",l="/projects/AiNovaPro/en/latest/assets/image4.6QG1EOCq.webp",c="/projects/AiNovaPro/en/latest/assets/image5.syu_iw7_.webp",d="/projects/AiNovaPro/en/latest/assets/image6.CN-4_c7-.webp",p="/projects/AiNovaPro/en/latest/assets/image7.BuiC3iil.webp",h="/projects/AiNovaPro/en/latest/assets/image8.BbK0GClB.webp",g="/projects/AiNovaPro/en/latest/assets/image9.CQUjcvIU.webp",m="data:image/png;base64,",u="/projects/AiNovaPro/en/latest/assets/image11.Bni9-Ykn.webp",b="/projects/AiNovaPro/en/latest/assets/image12.C59PflF7.webp",v="/projects/AiNovaPro/en/latest/assets/image13.vhdhRJgC.webp",f="/projects/AiNovaPro/en/latest/assets/image14.BY5LYkqT.webp",e="data:image/png;base64,",E=JSON.parse('{"title":"4. Lidar","description":"","frontmatter":{},"headers":[],"relativePath":"docs/4_LiDAR_Training_Program.md","filePath":"docs/4_LiDAR_Training_Program.md"}'),A={name:"docs/4_LiDAR_Training_Program.md"};function w(y,t,k,C,_,L){return n(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="_4-lidar" tabindex="-1">4. Lidar <a class="header-anchor" href="#_4-lidar" aria-label="Permalink to &quot;4. Lidar&quot;">​</a></h1><h2 id="_4-1-lidar-introduction" tabindex="-1">4.1 Lidar Introduction <a class="header-anchor" href="#_4-1-lidar-introduction" aria-label="Permalink to &quot;4.1 Lidar Introduction&quot;">​</a></h2><h3 id="_4-1-1-overview" tabindex="-1">4.1.1 Overview <a class="header-anchor" href="#_4-1-1-overview" aria-label="Permalink to &quot;4.1.1 Overview&quot;">​</a></h3><p>As a high-precision and high-speed remote sensing technology, Lidar plays a critical role in mapping, autonomous driving, environmental perception, and robotic navigation. This document introduces the principles, components, operating mechanisms, application areas, and advantages of Lidar, as well as its development trends.</p><p>Lidar holds a pivotal position in autonomous driving and intelligent transportation by providing real-time detection of obstacles, pedestrians, and vehicles on the road, while delivering precise distance and positional information. In robotic navigation and environmental perception, it supplies robots with accurate maps and detailed information about their surrounding environment. Furthermore, it is widely employed in 3D modeling and mapping, security monitoring, and remote sensing survey applications.</p><img loading="lazy" height="330" width="611" src="'+o+'" style="width:500px;" class="common_img"><h3 id="_4-1-2-lidar-components-and-classification" tabindex="-1">4.1.2 Lidar Components and Classification <a class="header-anchor" href="#_4-1-2-lidar-components-and-classification" aria-label="Permalink to &quot;4.1.2 Lidar Components and Classification&quot;">​</a></h3><p>Lidar consists of components such as laser transmitters, receivers and photoelectric detectors, scanning mechanisms and angle resolution. The laser emitter generates laser beams, while the receiver and photodetector capture the reflected light signals. The scanning mechanism is used to survey the surrounding environment, and the angle measurement system determines the position of target objects.</p><p>Based on the scanning method, Lidar can be functionally classified into the following types:</p><p><strong>Rotating Lidar:</strong> Performs full horizontal scanning of laser beams by rotating the laser emitter or scanning mechanism. It provides high scanning speed and measurement accuracy, and is widely employed in autonomous driving, 3D environment modeling, and mapping applications.</p><p><strong>Solid-State Lidar:</strong> Utilizes a solid-state laser emitter without any rotating components. It is typically more compact and lightweight, with lower power consumption, and is also suitable for applications such as mobile devices, drones, and robots.</p><p><strong>Mechanical Lidar:</strong> Uses mechanical components, such as rotating mirrors or prisms, to scan laser beams. It typically offers longer measurement ranges and higher accuracy, but with slower scanning speeds. Mechanical Lidar is widely applied in terrain surveying, building scanning, and navigation.</p><p><strong>Phase-Modulated Lidar:</strong> Measures the distance between target objects and the Lidar system by modulating the phase of the laser beam. It typically provides high measurement accuracy and extended range, and is widely used in mapping, surveying, and industrial applications.</p><p><strong>Flash Lidar:</strong> Illuminates the entire scene at once using a single, short-duration, high-power laser pulse, and captures the reflected light signals with a receiver array. It offers high speed and high resolution, making it suitable for rapid scene capture and motion tracking applications.</p><h3 id="_4-1-3-lidar-version-description" tabindex="-1">4.1.3 Lidar Version Description <a class="header-anchor" href="#_4-1-3-lidar-version-description" aria-label="Permalink to &quot;4.1.3 Lidar Version Description&quot;">​</a></h3><img loading="lazy" height="639" width="638" src="'+r+'" style="width:300px;" class="common_img"><p>The robot is equipped with MS200 laser radar by default, which uses connectors to connect to external systems for power supply and data reception.</p><ol><li><p>Power on the robot and connect via a remote desktop tool. For detailed connection instructions, refer to <a href="https://wiki.hiwonder.com/projects/LeRobot/en/latest/docs/1_LanderPi_User_Manual.html#development-environment-setup-and-configuration" target="_blank" rel="noreferrer">1.4 Development Environment Setup and Configuration</a>.</p></li><li><p>After a successful connection, double-click the <strong>Tool</strong> icon <img loading="lazy" height="86" width="73" src="'+l+'" style="width:30px;"> on the desktop.</p></li><li><p>Then click the <strong>Execute</strong> button to run the program:</p></li></ol><img loading="lazy" height="120" width="442" src="'+c+'" style="width:400px;" class="common_img"><ol start="4"><li>The interface is as follows:</li></ol><img loading="lazy" height="352" width="690" src="'+d+'" style="width:500px;" class="common_img"><ol start="5"><li>Click the dropdown button on the Lidar tab and select the model that matches your robot. For example, the robot is equipped by default with the MS200 Lidar. Then click <strong>Save</strong> and <strong>Apply</strong>.</li></ol><img loading="lazy" height="348" width="686" src="'+p+'" style="width:500px;" class="common_img"><ol start="6"><li>A popup window, as shown below, will appear. The robot&#39;s auto-start service will restart, and the Lidar model will be configured according to the selected option.</li></ol><img loading="lazy" height="352" width="686" src="'+h+'" style="width:500px;" class="common_img"><ol start="7"><li>After the restart is complete, click <strong>Exit</strong>.</li></ol><img loading="lazy" height="353" width="690" src="'+g+'" style="width:500px;" class="common_img"><ol start="8"><li>After switching, click the ROS2 command-line terminal icon <img loading="lazy" height="28" width="29" src="'+m+'"> to verify the Lidar version.</li></ol><img loading="lazy" height="220" width="609" src="'+u+'" style="width:500px;" class="common_img"><h2 id="_4-2-operating-principles-and-distance-measurement" tabindex="-1">4.2 Operating Principles and Distance Measurement <a class="header-anchor" href="#_4-2-operating-principles-and-distance-measurement" aria-label="Permalink to &quot;4.2 Operating Principles and Distance Measurement&quot;">​</a></h2><h3 id="_4-2-1-lidar-distance-measurement" tabindex="-1">4.2.1 Lidar Distance Measurement <a class="header-anchor" href="#_4-2-1-lidar-distance-measurement" aria-label="Permalink to &quot;4.2.1 Lidar Distance Measurement&quot;">​</a></h3><p>Common LiDAR systems use two methods to determine the distance to a target: triangulation and time-of-flight (TOF).</p><p>For TOF, as illustrated below, the Lidar emits a laser beam toward the target. The target reflects the light directly back to the Lidar, which calculates the time of flight. Multiplying this time by the speed of light yields the distance between the target and the Lidar.</p><img loading="lazy" height="284" width="820" src="'+b+'" style="width:500px;" class="common_img"><p>Triangulation can be understood with reference to the diagram below. During manufacturing, the Lidar is adjusted so that the laser is emitted at a specific angle rather than directly striking the target. This angle is preset and remains unchanged during operation. The distance from the target to the Lidar can then be calculated using trigonometric functions based on this angle.</p><img loading="lazy" height="313" width="809" src="'+v+'" style="width:500px;" class="common_img"><h3 id="_4-2-2-lidar-performance-and-results" tabindex="-1">4.2.2 Lidar Performance and Results <a class="header-anchor" href="#_4-2-2-lidar-performance-and-results" aria-label="Permalink to &quot;4.2.2 Lidar Performance and Results&quot;">​</a></h3><p>LiDAR emits laser beams that strike the surface of a target. When the Lidar receives the reflected light from the target, it marks the contours of the object at the points where the laser was reflected. Refer to the diagram below to understand the Lidar effect.</p><img loading="lazy" height="556" width="770" src="'+f+'" style="width:500px;" class="common_img"><h2 id="_4-3-lidar-obstacle-avoidance" tabindex="-1">4.3 Lidar Obstacle Avoidance <a class="header-anchor" href="#_4-3-lidar-obstacle-avoidance" aria-label="Permalink to &quot;4.3 Lidar Obstacle Avoidance&quot;">​</a></h2><p>The robot will detect the distance between the object in front of it and its body, and will turn left or right according to the set distance to avoid the obstacle. If no obstacle is encountered, it will continue to move forward.</p><p>This functionality can be enabled in two ways: either through the mobile app or by remotely connecting to the system and using commands.</p><p>For instructions on connecting the mobile app, refer to <a href="https://wiki.hiwonder.com/projects/LeRobot/en/latest/docs/1_LanderPi_User_Manual.html#app-control" target="_blank" rel="noreferrer">3.4 App Control</a>.</p><ol><li><p>Start the robot and connect it to the remote control software VNC. For details on connecting to the remote desktop, refer to <a href="https://wiki.hiwonder.com/projects/LeRobot/en/latest/docs/1_LanderPi_User_Manual.html#development-environment-setup-and-configuration" target="_blank" rel="noreferrer">1.4 Development Environment Setup and Configuration</a>.</p></li><li><p>Click the terminal icon <img loading="lazy" height="34" width="43" src="'+e+'" style="width:30px;"> in the system desktop to open a command-line window.</p></li></ol><ol start="3"><li>Enter the command to stop the APP auto-start service and press <strong>Enter</strong>.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.stop_ros.sh</span></span></code></pre></div><ol start="4"><li>Then enter the command and press <strong>Enter</strong> to start the robot&#39;s auto-start program:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch app lidar_node.launch.py debug:=true</span></span></code></pre></div><ol start="5"><li>Open another command-line terminal, enter the command, and press <strong>Enter</strong> to launch the Lidar function:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/enter std_srvs/srv/Trigger {}</span></span></code></pre></div><ol start="6"><li>Next, in the current command-line terminal, enter the command and press <strong>Enter</strong> to start the Lidar obstacle avoidance function:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/set_running interfaces/srv/SetInt64 &quot;{data: 1}&quot;</span></span></code></pre></div><ol start="7"><li>To stop the current function, enter the command in the same command-line terminal and press <strong>Enter</strong> to execute.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/set_running interfaces/srv/SetInt64 &quot;{data: 0}&quot;</span></span></code></pre></div><ol start="8"><li>To exit the function, simply press <strong>Ctrl + C</strong> in the terminal window from step 4 or 5.</li></ol><h2 id="_4-4-lidar-tracking" tabindex="-1">4.4 Lidar Tracking <a class="header-anchor" href="#_4-4-lidar-tracking" aria-label="Permalink to &quot;4.4 Lidar Tracking&quot;">​</a></h2><p>The robot detects the distance to objects directly in front of it. If the distance is greater than 35 cm, it follows the object. If less than 35 cm, it moves backward. The robot automatically stops when the distance to the object is exactly 35 cm.</p><p>This functionality can be enabled in two ways: either through the mobile app or by remotely connecting to the system and using commands.</p><p>For instructions on connecting the mobile app, refer to <a href="https://wiki.hiwonder.com/projects/LeRobot/en/latest/docs/1_LanderPi_User_Manual.html#app-control" target="_blank" rel="noreferrer">3.4 App Control</a>.</p><ol><li><p>Start the robot and connect it to the remote control software VNC. For details on connecting to the remote desktop, refer to <a href="https://wiki.hiwonder.com/projects/LeRobot/en/latest/docs/1_LanderPi_User_Manual.html#development-environment-setup-and-configuration" target="_blank" rel="noreferrer">1.4 Development Environment Setup and Configuration</a>.</p></li><li><p>Click the terminal icon <img loading="lazy" height="34" width="43" src="'+e+'" style="width:30px;"> in the system desktop to open a command-line window.</p></li></ol><ol start="3"><li><p>Enter the command to stop the APP auto-start service and press <strong>Enter</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.stop_ros.sh</span></span></code></pre></div></li><li><p>Enter the command and press <strong>Enter</strong> to start the local services for the app functions and the chassis control service:</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch app lidar_node.launch.py debug:=true</span></span></code></pre></div><ol start="5"><li>Open another command-line terminal, enter the command, and press <strong>Enter</strong> to launch the Lidar function:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/enter std_srvs/srv/Trigger {}</span></span></code></pre></div><ol start="6"><li>Next, in the current command-line terminal, enter the command and press <strong>Enter</strong> to start the Lidar obstacle avoidance function:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/set_running interfaces/srv/SetInt64 &quot;{data: 2}&quot;</span></span></code></pre></div><ol start="7"><li>To stop the current function, enter the command in the same command-line terminal and press <strong>Enter</strong> to execute.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/set_running interfaces/srv/SetInt64 &quot;{data: 0}&quot;</span></span></code></pre></div><ol start="8"><li>To exit the function, simply press <strong>Ctrl + C</strong> in the terminal window from step 4 or 5.</li></ol><h2 id="_4-5-lidar-guard" tabindex="-1">4.5 Lidar Guard <a class="header-anchor" href="#_4-5-lidar-guard" aria-label="Permalink to &quot;4.5 Lidar Guard&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The Lidar Guard function is not supported when the LanderPi is in Ackermann configuration.</strong></p></div><p>The robot will detect the distance between the object in front of it and its body. If there is an object within the set distance, it will turn and the body will always face the object.</p><p>This functionality can be enabled in two ways: either through the mobile app or by remotely connecting to the system and using commands.</p><p>For instructions on connecting the mobile app, refer to <a href="https://wiki.hiwonder.com/projects/LeRobot/en/latest/docs/1_LanderPi_User_Manual.html#app-control" target="_blank" rel="noreferrer">3.4 App Control</a>.</p><ol><li><p>Start the robot and connect it to the remote control software VNC. For details on connecting to the remote desktop, refer to <a href="https://wiki.hiwonder.com/projects/LeRobot/en/latest/docs/1_LanderPi_User_Manual.html#development-environment-setup-and-configuration" target="_blank" rel="noreferrer">1.4 Development Environment Setup and Configuration</a>.</p></li><li><p>Click the terminal icon <img loading="lazy" height="34" width="43" src="'+e+'" style="width:30px;"> in the system desktop to open a command-line window.</p></li></ol><ol start="3"><li>Enter the command to stop the app auto-start service and press <strong>Enter</strong>.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.stop_ros.sh</span></span></code></pre></div><ol start="4"><li>Enter the command and press <strong>Enter</strong> to start the local services for the app functions and the chassis control service:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch app lidar_node.launch.py debug:=true</span></span></code></pre></div><ol start="5"><li>Open a new ROS2 command-line terminal, enter the command, and press <strong>Enter</strong> to launch the Lidar function:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/enter std_srvs/srv/Trigger {}</span></span></code></pre></div><ol start="6"><li>Create a new command line terminal, enter the command, and press <strong>Enter</strong> to enable radar obstacle avoidance function:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/set_running interfaces/srv/SetInt64 &quot;{data: 3}&quot;</span></span></code></pre></div><ol start="7"><li>To stop the current function, enter the command in the same command-line terminal and press <strong>Enter</strong> to execute.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/set_running interfaces/srv/SetInt64 &quot;{data: 0}&quot;</span></span></code></pre></div><ol start="8"><li>To exit the function, simply press <strong>Ctrl + C</strong> in the terminal window from step 4 or 5.</li></ol>',86)])])}const q=a(A,[["render",w]]);export{E as __pageData,q as default};
